 contexte:{actions:['Vérifier terrain, hémodilution et évolution de l’Hb.'],course:['213-1']},
 vgm:{actions:['Lire le VGM sur la NFS.','Repères du cours : 80 et 100 fL.'],body:['Convention retenue pour rester cohérent avec le cours 213-7 : microcytose < 80 fL ; normocytose de 80 à 100 fL ; macrocytose > 100 fL.','L’ancien arbre citait une limite LiSA de 98 fL. Les conventions diffèrent selon les supports : entre 98 et 100 fL, confronter le résultat aux normes du laboratoire et au contexte, sans faire dépendre toute l’enquête de cette frontière.'],choices:[choice('< 80 fL','micro'),choice('80–100 fL','retic-normo'),choice('> 100 fL','retic-macro')],course:['213-7'],refs:['hemato']},
